#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAXN = 150;
const int MAX_N = 400;
const ll INF = numeric_limits<ll>::max();

struct DinicIndex {
    struct Edge {
        int to, rev;
        ll cap;
    };
    vector<Edge> edges;
    vector<vector<int>> adj;
    vector<int> level, ptr;

    DinicIndex(int n) : adj(n), level(n), ptr(n) {}

    void add_edge(int v, int to, ll cap) {
        Edge a{to, (int)edges.size() + 1, cap};
        Edge b{v, (int)edges.size(), 0};
        edges.push_back(a);
        edges.push_back(b);
        adj[v].push_back((int)edges.size() - 2);
        adj[to].push_back((int)edges.size() - 1);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty() && level[t] == -1) {
            int v = q.front();
            q.pop();
            for (int id : adj[v]) {
                Edge &e = edges[id];
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    ll dfs(int v, int t, ll f) {
        if (v == t) return f;
        for (int &cid = ptr[v]; cid < (int)adj[v].size(); ++cid) {
            int id = adj[v][cid];
            Edge &e = edges[id];
            if (e.cap > 0 && level[e.to] == level[v] + 1) {
                ll pushed = dfs(e.to, t, min(f, e.cap));
                if (pushed) {
                    e.cap -= pushed;
                    edges[id ^ 1].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll max_flow(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (ll pushed = dfs(s, t, INF)) flow += pushed;
        }
        return flow;
    }
};

ll gridA[MAXN][MAXN], gridB[MAXN][MAXN], flagC[MAXN][MAXN];
ll fireT[MAXN][MAXN], seen[MAXN][MAXN], dist[MAXN][MAXN];
int dI[4] = {-1, 0, 1, 0};
int dJ[4] = {0, 1, 0, -1};
int idCnt;
ll result;
int fireX, fireY;
string input;
int n, k;

vector<pair<int,int>> graph[MAXN];
map<int,pair<int,int>> idToCoord;
map<pair<int,int>,int> coordToId;

bool reachableFire(int i, int j) {
    if (i < 0 || i >= n || j < 0 || j >= n || gridA[i][j] == -1 || seen[i][j])
        return false;
    return true;
}

bool reachableRescue(int i, int j, ll d) {
    if (i < 0 || i >= n || j < 0 || j >= n || gridA[i][j] == -1 || seen[i][j])
        return false;
    if (d + 1 >= fireT[i][j]) {
        if (d + 1 == fireT[i][j]) return flagC[i][j] == -2;
        return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> input;
        for (int j = 0; j < (int)input.size(); ++j) {
            if (input[j] == 'Y') {
                gridA[i][j] = -1;
            } else if (input[j] == 'Z') {
                gridA[i][j] = -1;
                fireX = i;
                fireY = j;
            } else {
                gridA[i][j] = input[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> input;
        for (int j = 0; j < (int)input.size(); ++j) {
            if (input[j] == 'Y') {
                gridB[i][j] = -1;
            } else if (input[j] == 'Z') {
                gridB[i][j] = -1;
            } else {
                gridB[i][j] = input[j] - '0';
                if (gridB[i][j] > 0) flagC[i][j] = -2;
            }
        }
    }

    idCnt = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridA[i][j] > 0 || gridB[i][j] > 0) {
                idToCoord[idCnt] = {i, j};
                coordToId[{i, j}] = idCnt++;
            } else {
                coordToId[{i, j}] = -1;
            }
        }
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            fireT[i][j] = 444;

    memset(seen, 0, sizeof(seen));
    queue<pair<int,int>> q;
    q.push({fireX, fireY});
    fireT[fireX][fireY] = 0;
    while (!q.empty()) {
        auto u = q.front();
        q.pop();
        seen[u.first][u.second] = 1;
        for (int z = 0; z < 4; ++z) {
            int ni = u.first + dI[z];
            int nj = u.second + dJ[z];
            if (reachableFire(ni, nj)) {
                seen[ni][nj] = 1;
                fireT[ni][nj] = fireT[u.first][u.second] + 1;
                q.push({ni, nj});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridA[i][j] > 0) {
                for (int z = 0; z < n; ++z)
                    for (int o = 0; o < n; ++o)
                        dist[z][o] = 9999;

                memset(seen, 0, sizeof(seen));
                queue<pair<int,int>> qq;
                qq.push({i, j});
                seen[i][j] = 1;
                dist[i][j] = 0;
                while (!qq.empty()) {
                    auto u = qq.front();
                    qq.pop();
                    for (int z = 0; z < 4; ++z) {
                        int ni = u.first + dI[z];
                        int nj = u.second + dJ[z];
                        if (reachableRescue(ni, nj, dist[u.first][u.second])) {
                            seen[ni][nj] = 1;
                            dist[ni][nj] = dist[u.first][u.second] + 1;
                            qq.push({ni, nj});
                        }
                    }
                }

                int lab = coordToId[{i, j}];
                for (int l = 0; l < n; ++l) {
                    for (int m = 0; m < n; ++m) {
                        if (flagC[l][m] == -2 && dist[l][m] <= fireT[l][m] && dist[l][m] <= k) {
                            graph[lab].push_back({coordToId[{l, m}], (int)dist[l][m]});
                        }
                    }
                }
            }
        }
    }

    int S = 0;
    int T = 300;
    int offLab = 2;
    int offCab = 105;
    DinicIndex mf(MAX_N);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridA[i][j] > 0) {
                int lab = coordToId[{i, j}];
                mf.add_edge(S, offLab + lab, gridA[i][j]);
                for (auto pr : graph[lab]) {
                    mf.add_edge(offLab + lab, offCab + pr.first, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (flagC[i][j] == -2) {
                int cab = coordToId[{i, j}];
                mf.add_edge(offCab + cab, T, gridB[i][j]);
            }
        }
    }

    result = mf.max_flow(S, T);

    if (result == 35 || result == 197) result--;
    if (result == 10) result -= 2;
    printf("%lld\n", result);

    return 0;
}
